async function searchIeProducts(query, limit) {
  const q = query.toLowerCase();
  const rows = await db.selectFrom("ie_products as ip").leftJoin(
    "ie_product_substances as ips",
    "ip.product_id",
    "ips.product_id"
  ).select([
    "ip.product_id",
    "ip.product_name",
    "ip.pcs_number",
    "ip.auth_holder",
    sql`string_agg(ips.substance_name, ', ')`.as(
      "substances_agg"
    ),
    sql`similarity(ip.product_name, ${query})`.as("sim")
  ]).where(
    (eb) => eb.or([
      eb(sql`LOWER(ip.product_name)`, "like", `${q}%`),
      eb(sql`similarity(ip.product_name, ${query})`, ">", 0.35)
    ])
  ).groupBy([
    "ip.product_id",
    "ip.product_name",
    "ip.pcs_number",
    "ip.auth_holder"
  ]).orderBy(
    sql`CASE WHEN LOWER(ip.product_name) = ${q} THEN 0
           WHEN LOWER(ip.product_name) LIKE ${q + "%"} THEN 1
           ELSE 2 END`,
    "asc"
  ).orderBy("sim", "desc").limit(limit).execute();
  return rows.map((r) => {
    const nameLower = (r.product_name ?? "").toLowerCase();
    let matchType;
    if (nameLower === q) matchType = "exact_name";
    else if (nameLower.startsWith(q)) matchType = "prefix";
    else matchType = "fuzzy";
    return {
      type: "product",
      match_field: "product_name",
      match_type: matchType,
      entity: {
        product_name: r.product_name ?? "",
        country: "IE",
        identifier: r.pcs_number ?? "",
        auth_holder: r.auth_holder,
        status: "Authorised",
        substances: r.substances_agg ? r.substances_agg.split(", ") : []
      }
    };
  });
}
