  return sorted.map((data) => ({
    type: "company",
    match_field: "auth_holder",
    match_type: data.displayName.toLowerCase().startsWith(q) ? "prefix" : "fuzzy",
    entity: {
      company_name: data.displayName,
      ie_product_count: data.ie,
      fr_product_count: data.fr
    }
  }));
