async function fetchOftData(casNumber) {
  const empty41 = {
    toxRefValues: [],
    genotoxicity: {
      conclusion: null,
      in_vitro_link: null,
      in_vivo_link: null
    },
    metabolites: [],
    dossiers: []
  };
  if (!casNumber || casNumber === "No CAS allocated" || casNumber === "See note") {
    return empty41;
  }
  const refSub = await db.selectFrom("oft_reference_substances").select("uuid").where("cas_number", "=", casNumber).executeTakeFirst();
  if (!refSub) return empty41;
  const oftSub = await db.selectFrom("oft_substances").select("uuid").where("ref_substance_uuid", "=", refSub.uuid).executeTakeFirst();
  if (!oftSub) return empty41;
  const substanceUuid = oftSub.uuid;
  const [toxRefValues, endpointSummaries, metabolites, dossiers] = await Promise.all([
    // Tox reference values (ADI, ARfD, AOEL from OFT)
    db.selectFrom("oft_tox_ref_values").select([
      "endpoint_type",
      "value_lower",
      "value_upper",
      "unit",
      "assessment_body",
      "critical_endpoint",
      "justification",
      "not_allocated",
      "population"
    ]).where("substance_uuid", "=", substanceUuid).execute(),
    // Endpoint summaries (genotoxicity) — real data is in key_information,
    // NOT the formal genotox_in_vitro/genotox_in_vivo fields (mostly null in OFT 3.0)
    db.selectFrom("oft_endpoint_summaries").select([
      "key_information",
      "genotox_in_vitro_study_link",
      "genotox_in_vivo_study_link"
    ]).where("substance_uuid", "=", substanceUuid).where("definition", "=", "ENDPOINT_SUMMARY.GeneticToxicity").execute(),
    // Metabolites
    db.selectFrom("oft_metabolites as m").leftJoin(
      "oft_reference_substances as rs",
      "rs.uuid",
      "m.metabolite_substance_uuid"
    ).select([
      "rs.reference_substance_name as name",
      "m.metabolite_uuid as uuid",
      "m.remarks"
    ]).where("m.parent_substance_uuid", "=", substanceUuid).execute(),
    // Dossiers + their docs
    fetchOftDossiers(substanceUuid)
  ]);
  let genotoxConclusion = null;
  let inVitroLink = null;
  let inVivoLink = null;
  if (endpointSummaries.length > 0) {
    const conclusions = endpointSummaries.map((r) => r.key_information).filter(Boolean);
    genotoxConclusion = conclusions.length > 0 ? conclusions.join("; ") : null;
    inVitroLink = endpointSummaries.find((r) => r.genotox_in_vitro_study_link)?.genotox_in_vitro_study_link ?? null;
    inVivoLink = endpointSummaries.find((r) => r.genotox_in_vivo_study_link)?.genotox_in_vivo_study_link ?? null;
  }
  return {
    toxRefValues,
    genotoxicity: {
      conclusion: genotoxConclusion,
      in_vitro_link: inVitroLink,
      in_vivo_link: inVivoLink
    },
    metabolites: metabolites.map((m2) => ({
      name: m2.name,
      uuid: m2.uuid,
      remarks: m2.remarks
    })),
    dossiers
  };
}
