async function searchProducts(params2) {
  const country = params2.country ?? "both";
  const limit = Math.min(params2.limit ?? 50, 200);
  const offset = params2.offset ?? 0;
  const iePromise = country === "fr" ? Promise.resolve({
    results: [],
    total: 0
  }) : searchIeProducts2(params2, limit, offset);
  const frPromise = country === "ie" ? Promise.resolve({
    results: [],
    total: 0
  }) : searchFrProducts2(params2, limit, offset);
  const [ie2, fr2] = await Promise.all([iePromise, frPromise]);
  let results;
  if (country === "both") {
    results = [...ie2.results, ...fr2.results].sort(
      (a2, b2) => (a2.product_name ?? "").localeCompare(b2.product_name ?? "")
    ).slice(0, limit);
  } else {
    results = country === "ie" ? ie2.results : fr2.results;
  }
  return {
    results,
    total_ie: ie2.total,
    total_fr: fr2.total,
    limit,
    offset
  };
}
