async function getIeProductDetail(pcsNumber) {
  const product = await db.selectFrom("ie_products").selectAll().where("pcs_number", "=", pcsNumber).executeTakeFirst();
  if (!product) return null;
  const [substances, crops] = await Promise.all([
    db.selectFrom("ie_product_substances").select(["substance_name", "concentration"]).where("product_id", "=", product.product_id).execute(),
    db.selectFrom("ie_product_crops").select("crop_name").where("product_id", "=", product.product_id).orderBy("crop_name").execute()
  ]);
  return {
    country: "ie",
    product_name: product.product_name,
    pcs_number: product.pcs_number,
    auth_holder: product.auth_holder,
    marketing_company: product.marketing_company,
    product_type: product.product_type,
    function_name: product.function_name,
    user_type: product.user_type,
    substances: substances.map((s) => ({
      substance_name: s.substance_name,
      concentration: s.concentration
    })),
    crops: crops.map((c) => c.crop_name),
    data_as_of: product.last_synced_at ? new Date(
      product.last_synced_at
    ).toISOString() : null
  };
}
